entries[180721] = { ["name"] = "Enchanted Dreamlight Runestag", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nSell Price:\n\"The majestic runestags are capable of siphoning anima from the ambient light of Ardenweald with their elaborate antlers. The anima is used as nourishment and to power the runestag's speed and magic.\"\nCovenant:\nNight Fae\nZone:\nArdenweald" }
entries[180722] = { ["name"] = "Enchanted Shadeleaf Runestag", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires Renown 39\nSell Price:\n\"A shadeleaf runestag is capable of goring creatures as powerful as a gorm matriarch in defense of its herd. The Wild Hunt ride these mounts into dangerous corners of the Shadowlands, when their domain must be defended from those who would threaten the wilds.\"\nCovenant:\nNight Fae\nZone:\nArdenweald" }
entries[180723] = { ["name"] = "Enchanted Wakener's Runestag", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nSell Price:\n\"Wakener runestags fiercely protect their wildseed groves. When the groves starting to fail, many runestags went berserk.\"\nCovenant:\nNight Fae\nZone:\nArdenweald" }
entries[180724] = { ["name"] = "Enchanted Winterborn Runestag", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires Marasmius\n- Revered\nSell Price:\n\"Winterborn runestags are the favored mount of the Winter Queen herself, and she only bestows such a creature on her most favored subjects.\"\nCovenant:\nNight Fae\nZone:\nArdenweald" }
entries[180725] = { ["name"] = "Spinemaw Gladechewer", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nSell Price:\n\"Spriggan riders tie bits of anima-less detritus to the end of sticks in front of their gorm mounts to steer. It's... an imperfect art.\"\nDrop:\nGormtamer Tizo\nZone:\nArdenweald" }
entries[180726] = { ["name"] = "Pale Acidmaw", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nYou must be Exalted with the Stitchmasters.\nEarn the Bare Necessities achievement to purchase this mount.\nSell Price:\n\"The acid present in the ichor of this creature sapped away the color from its shell, leaving it a striking shade of snowy white.\"\nCovenant Feature:\nThe Ember Court\nCovenant:\nVenthyr\n\nCovenant Feature:\nQueen's Conservatory\nCovenant:\nNight Fae\n\nCovenant Feature:\nPath of Ascension\nCovenant:\nKyrian\n\nCovenant Feature:\nAbomination Factory\nCovenant:\nNecrolord" }
entries[180727] = { ["name"] = "Shimmermist Runner", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nSell Price:\n\"Mischievous spriggans and the valerunners have a natural enmity. No valerunner would deign to allow a spriggan rider because they can sense their inherent malevolence. This angers the trickster spriggans who take twisted enjoyment in playing cruel pranks on these majestic creatures.\"\nArea:\nMistveil Tangle\nZone:\nArdenweald" }
entries[180728] = { ["name"] = "Swift Gloomhoof", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nSell Price:\n\"The ballads of Ardenweald claim that the birth of gloomrunner heralds the passing of a particularly benevolent wild god. Seeing a gloomrunner is therefore a blessing and a curse.\"\nDrop:\nNight Mare\nZone:\nArdenweald" }
entries[180729] = { ["name"] = "Duskflutter Ardenmoth", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires The Wild Hunt\n- Exalted\nSell Price:\n\"These ardenmoths prefer the dark and damp forests of northwest Ardenweald, where fungal colonies are perpetually blooming.\"\nVendor:\nAithlyn\nZone:\nArdenweald\nFaction:\nThe Wild Hunt - Exalted\nCost:" }
entries[180730] = { ["name"] = "Wild Glimmerfur Prowler", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nSell Price:\n\"This prowler's brilliant green coat distinguishes it from the blues and purples of Ardenweald, making it much easier for others of its kind to see through the midnight woods.\"\nDrop:\nValfir the Unrelenting\nCovenant:\nNight Fae\nZone:\nArdenweald" }
entries[180731] = { ["name"] = "Wildseed Cradle", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nSell Price:\n\"The most precious cargo in all Ardenweald, the wildseeds, are cradled by this lovingly-crafted cart. It is imbued with anima to allow it to hover over the ground.\"\nTreasure:\nCache of the Moon\nZone:\nArdenweald" }
