entries[180748] = { ["name"] = "Silky Shimmermoth", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nParticipate in seven different performances at the Star Lake Amphitheater.\nSell Price:\n\"The moths of Ardenweald play a vital role in the ecosystem, carrying spores, anima, and pollen from one part of the forest to the other, providing nourishment and variation to the denizens living below.\"\nVendor:\nMaster Clerk Salorn\nZone:\nArdenweald\nCost:\n5000" }
