entries[180761] = { ["name"] = "Phalynx of Loyalty", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Some within the Ascended keep a phalynx as a pet. While they may not be as furry as a larion, they are much less likely to eat your other pets.\"\nCovenant:\nKyrian\nZone:\nBastion" }
entries[180762] = { ["name"] = "Phalynx of Humility", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"The phalynx does not fetch, though it is not known why this is.\"\nCovenant:\nKyrian\nZone:\nBastion" }
entries[180763] = { ["name"] = "Phalynx of Courage", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"A phalynx is considered both a worthy companion and a lithe opponent to test one's reflexes against.\"\nCovenant:\nKyrian\nZone:\nBastion" }
entries[180764] = { ["name"] = "Phalynx of Purity", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires Renown 23\n\n\"Little is known about the origination of phalynx technology, the machinations of which are taught more akin to religion than engineering.\"\nCovenant:\nKyrian\nZone:\nBastion" }
entries[180765] = { ["name"] = "Eternal Phalynx of Purity", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires Renown 39\n\n\"The armored phalynx is a favorite companion of the mightiest warriors of the Ascended as it is both fearless and vicious in battle.\"\nCovenant:\nKyrian\nZone:\nBastion" }
entries[180766] = { ["name"] = "Eternal Phalynx of Courage", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Many bars of gildenite are required to forge one of these sparkling mounts, but the sight of them alone is worth the gathering time.\"\nCovenant:\nKyrian\nZone:\nBastion" }
entries[180767] = { ["name"] = "Eternal Phalynx of Loyalty", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nEarn the Death Foursworn achievement to purchase this mount.\n\n\"A marvel of steward engineering, the armored phalynx is a rare and awe-inspiring sight.\"\nCovenant:\nKyrian\nZone:\nBastion" }
entries[180768] = { ["name"] = "Eternal Phalynx of Humility", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nEarn the Learning from the Masters achievement to purchase this mount.\n\n\"When an armored phalynx is forged, stewards clap their hammers together in reverence of the skill required in its creation.\"\nCovenant:\nKyrian\nZone:\nBastion" }
