entries[180945] = { ["name"] = "Crypt Gargon", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Loyal hounds of the Curator, these gargon patrol the crypts and catacombs deterring both trespassing and escape.\"\nCovenant:\nVenthyr\nZone:\nRevendreth" }
entries[180946] = { ["name"] = "Blessed Armament", ["text"] = "Quest Item" }
entries[180947] = { ["name"] = "Tithe Collector's Vessel", ["text"] = "Binds when picked up\nToy\nUse: Place the Tithe Collector's Vessel on your back for 15 min. (1 Hour Cooldown)" }
entries[180948] = { ["name"] = "Battle Gargon Vrednic", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Prince Renathal's loyal gargon, Vrednic has been by his side for millennia. Adorned in his Sinvyr armor, Vrednic's mere presence instills terror to all those who lay eyes on him as he ushers his rider into battle.\"\nCovenant:\nVenthyr\nZone:\nRevendreth" }
entries[180949] = { ["name"] = "Animaflow Stabilizer", ["text"] = "Permanent Upgrade: The Maw\nBinds when picked up\nUnique\nUse: Unlock the Animaflow Teleporter in Ve'nari's Refuge, allowing you to travel quickly to The Tremaculum.\nRequires that Ve'nari has a Tentative or higher opinion of you." }
entries[180950] = { ["name"] = "The Maw - Pet Cosmetic - NYI", ["text"] = "Binds when picked up\n\"Very cute, but possibly lethal to all life on Azeroth.\"" }
entries[180951] = { ["name"] = "The Maw - POI Unlock - NYI", ["text"] = "Binds when picked up\n\"Unlocks access to a Point of Interest in The Maw\"" }
entries[180952] = { ["name"] = "Possibility Matrix", ["text"] = "Permanent Upgrade: Torghast\nBinds when picked up\nUnique\nUse: Come to a better understanding of the infinite possibilities of Anima, expanding your selection of powers within Torghast. You will always see at least two choices when using an Anima Hoard.\nRequires that Ve'nari has an Appreciative or higher opinion of you.\n\"The hand of fate can be guided, after all.\"" }
entries[180953] = { ["name"] = "Soultwinning Scepter", ["text"] = "Binds when picked up\nUse: Bond your soul with that of a nearby ally, increasing all primary stats of your ally and yourself by 5%. (5 Min Cooldown)\n10 Charges\nRequires that Ve'nari has an Apprehensive or higher opinion of you.\nSell Price:" }
