entries[181300] = { ["name"] = "Gruesome Flayedwing", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nYou must be Exalted with the Stitchmasters.\nEarn the All The Colors of the Painbow achievement to purchase this mount.\n\n\"The flayedwings of Maldraxxus are prized for their ability to soar effortlessly through the skies of the Shadowlands, allowing their rider a surprise opportunity to strike at their foes or support their allies.\"\nCovenant Feature:\nThe Ember Court\nCovenant:\nVenthyr\n\nCovenant Feature:\nQueen's Conservatory\nCovenant:\nNight Fae\n\nCovenant Feature:\nPath of Ascension\nCovenant:\nKyrian\n\nCovenant Feature:\nAbomination Factory\nCovenant:\nNecrolord" }
