entries[181316] = { ["name"] = "Silvertip Dredwing", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nYou must be Exalted with the Stitchmasters.\nRequires Exalted with The Ember Court.\nEarn the Curse of Thirst achievement to purchase this mount.\n\n\"Bred by the Revendreth prince, Renathal, these rare dredwing are fiercely loyal and will only let those deemed worthy by the prince himself to interact with them.\"\nCovenant Feature:\nThe Ember Court\nCovenant:\nVenthyr\n\nCovenant Feature:\nQueen's Conservatory\nCovenant:\nNight Fae\n\nCovenant Feature:\nPath of Ascension\nCovenant:\nKyrian\n\nCovenant Feature:\nAbomination Factory\nCovenant:\nNecrolord" }
entries[181317] = { ["name"] = "Dauntless Duskrunner", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nYou must be Exalted with the Stitchmasters.\n\n\"The Path of Ascension is a challenging trial, and those that display all of the facets the Kyrian hold dear will be duly rewarded.\"\nCovenant Feature:\nThe Ember Court\nCovenant:\nVenthyr\n\nCovenant Feature:\nQueen's Conservatory\nCovenant:\nNight Fae\n\nCovenant Feature:\nPath of Ascension\nCovenant:\nKyrian\n\nCovenant Feature:\nAbomination Factory\nCovenant:\nNecrolord" }
