entries[181358] = { ["name"] = "Master Duelist's Chit", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+14 [Agility or Strength]\nEquip: Your attacks have a chance to deal 232 additional physical damage.\nSell Price:" }
entries[181359] = { ["name"] = "Overflowing Ember Mirror", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+14 [Agility or Strength or Intellect]\nUse: Gain an absorb shield preventing 20% of the damage done to you in the next 12 sec, up to a total of 3635 damage done. 33% of the remaining absorption explodes splitting the damage between all enemies within 8 yds. (2 Min, 30 Sec Cooldown)\nSell Price:" }
entries[181360] = { ["name"] = "Brimming Ember Shard", ["text"] = "Binds when picked up\nUnique-Equipped\nTrinket\n+ 20 Versatility\nUse: Channel on a friendly target to restore up to [ 4106 * (1 + Versatility)] health over 6 sec split between all allies bathed in the 40 yd beam. Channel on an enemy target dealing up to [ 3046 * (1 + Versatility)] Holy damage over 6 sec split amongst enemies caught in the 40 yd beam. Damage and Healing are increased slightly for each target hit. (1 Min, 30 Sec Cooldown)\nSell Price:" }
entries[181361] = { ["name"] = "Court Gossip", ["text"] = "Ember Court\nBinds when picked up\nUse: Start a rumor that will spread to nearby Humanoids.\n\n+Exciting for each person it reaches.\n\"Prince Renathal would like to contain such idle gossip. ( +Relaxing )\"" }
entries[181362] = { ["name"] = "Blob of Slime", ["text"] = "Ember Court\nBinds when picked up\nUse: Release the blob. ( + Messy )\n\"Prince Renathal might like to contain this mess. ( +Clean )\"" }
