entries[181483] = { ["name"] = "Spool of Silkstrider Thread", ["text"] = "Binds when picked up\n\"The gossamer appearance of silkstrider thread belies its great tensile strength which enables it to be utilized as a bowstring for both war and merriment.\"\nSell Price:" }
entries[181484] = { ["name"] = "Songwood Graft", ["text"] = "Binds when picked up\n\"Wood coaxed from mature trees is grafted onto saplings to improve their vitality and ensure bountiful anima harvests.\"\nSell Price:" }
entries[181485] = { ["name"] = "Jeweled Amber Leaf", ["text"] = "Binds when picked up\n\"Rather than metalwork, the night fae fashion amber into both useful tools and decorative objects.\"\nSell Price:" }
entries[181486] = { ["name"] = "Leafscale Coat", ["text"] = "Binds when picked up\n\"The leaves growing atop the runestags of Ardenweald are utilized by the night fae in lieu of their fur, so the animal can remain unharmed.\"\nSell Price:" }
entries[181487] = { ["name"] = "Glowberry Bead String", ["text"] = "Binds when picked up\n\"Glowberries can shimmer for decades when properly pulped and dried.\"\nSell Price:" }
entries[181488] = { ["name"] = "Shadowstalker Claw", ["text"] = "Binds when picked up\n\"When a shadowstalker population grows too quickly, a hunt is called to cull their numbers.\"\nSell Price:" }
entries[181489] = { ["name"] = "Star Lake Sonnets", ["text"] = "Binds when picked up\n\"The performative revelry displayed at the Star Lake Ampitheater provides reprieve from the constant vigil required to nurture wildseeds.\"\nSell Price:" }
entries[181490] = { ["name"] = "Wild Godrune", ["text"] = "Binds when picked up\n\"Spirit Tenders who hold vigil over the rebirth of Wild Gods often fill quiet hours carving their gods' likenesses as keepsakes.\"\nSell Price:" }
entries[181491] = { ["name"] = "Gormgris Lamp", ["text"] = "Binds when picked up\n\"Gormgris's natural luminosity provides an excellent light source for visitors unaccustomed to Ardenweald's perpetual twilight.\"\nSell Price:" }
entries[181492] = { ["name"] = "Petrified Faeflower", ["text"] = "Binds when picked up\n\"Petrified flowers are a gift given between friends and lovers, their never-wilting state symbolizing an eternal relationship.\"\nSell Price:" }
entries[181495] = { ["name"] = "Jade Bond", ["text"] = "Binds when picked up\nUse: Add this Conduit to your collection at the Forge of Bonds.\n\nAbilities that activate Gust of Mist reduce the cooldown on [ Invoke Chi-Ji, the Red Crane / Invoke Yul'on, the Jade Serpent] by 0.3 sec, and [ Invoke Chi-Ji, the Red Crane : Chi-Ji's Gusts of Mists / Yu'lon's Soothing Breath] healing is increased by 6.3% ." }
entries[181496] = { ["name"] = "Endmire Blossom", ["text"] = "Quest Item\n\"Its petals emit a soft glow and pungent smell.\"" }
entries[181497] = { ["name"] = "Interrogator's Key", ["text"] = "Quest Item\nUnique\nUse: Unlocks an Interrogator's Cage.\n\"The chipped teeth and worn bow suggest this key has long served its purpose.\"" }
entries[181498] = { ["name"] = "Grounding Surge", ["text"] = "Binds when picked up\nUse: Add this Conduit to your collection at the Forge of Bonds.\n\nSuccessfully interrupting an enemy with Counterspell reduces its cooldown by 2.5 sec ." }
