entries[181504] = { ["name"] = "Infernal Cascade", ["text"] = "Binds when picked up\nUse: Add this Conduit to your collection at the Forge of Bonds.\n\nWhile Combustion is active, your Fire Blast grants you 7.0% increased Fire damage for 5 sec, stacking up to 2 times." }
