entries[181715] = { ["name"] = "Temel's Certificate of Completion", ["text"] = "Binds when picked up\n\"This certificate signifies that the bearer has sufficent skills to hold an Ember Court, after successfully making The Party Herald happy in the course of their trial soiree.\"\nSell Price:" }
entries[181716] = { ["name"] = "Recruiting Posters", ["text"] = "Quest Item\nUnique\n\"Broadsheet that extols the benefits of serving in Nadjia's security troop.\"\n<Right Click to Read>" }
entries[181718] = { ["name"] = "Ligneous Phaedrum Ore", ["text"] = "Quest Item" }
entries[181719] = { ["name"] = "Monolithic Oxxein Ore", ["text"] = "Quest Item" }
entries[181720] = { ["name"] = "Menacing Sinvyr Ore", ["text"] = "Quest Item" }
entries[181721] = { ["name"] = "Ascendent Valor Signet", ["text"] = "Binds when picked up\nUnique-Equipped\nFinger\n+12 Stamina\n+ 18 Haste\n+ 22 Mastery\nSell Price:" }
entries[181722] = { ["name"] = "Antiquated Verdigris Coin", ["text"] = "Binds when picked up\n\"Once a symbol of success in the arena in Maldraxxus, the visage of the Primus is etched onto the coin.\"\nSell Price:" }
entries[181723] = { ["name"] = "Meticulously Pickled Head", ["text"] = "Binds when picked up\n\"Preservation of knowledge means something else entirely in Maldraxxus.\"\nSell Price:" }
entries[181724] = { ["name"] = "Tactics Vol. 83: Exploitation of Weather", ["text"] = "Binds when picked up\n\"Recognizing the material composition of your foe's armaments, and thus their resemblance to a lightning rod, may dictate how weather-manipulating magics can be utilized.\"\nSell Price:" }
entries[181725] = { ["name"] = "Prized Guardian's Medal", ["text"] = "Binds when picked up\n\"Defenders of Maldraxxus are given a medal in honor of their service to protect the Shadowlands.\"\nSell Price:" }
entries[181726] = { ["name"] = "Warfare Vol. 27: Behind Enemy Lines", ["text"] = "Binds when picked up\n\"Travelling as a prisoner is often more expeditious than remaining undetected.\"\nSell Price:" }
entries[181727] = { ["name"] = "Devoid Reinforced Flasks", ["text"] = "Binds when picked up\n\"Triple-walled flasks are essential in containing the deadly liquids used by the House of Plagues for their experiments.\"\nSell Price:" }
entries[181728] = { ["name"] = "Pristine Fleshstitcher Needles", ["text"] = "Binds when picked up\n\"Carved from the very bones of Maldraxxus, these needles are a prized output of the House of Constructs.\"\nSell Price:" }
entries[181729] = { ["name"] = "Prototype Phylactery Mold", ["text"] = "Binds when picked up\n\"The House of Liches are constantly working to improve their phylacteries to be more resilient to those seeking to destroy them.\"\nSell Price:" }
entries[181730] = { ["name"] = "Forged Oxxein Whetstone", ["text"] = "Binds when picked up\n\"Disciplined soldiers in Maldraxxus keep their weapons sharp and honed, ready to defend the Shadowlands at any cost.\"\nSell Price:" }
entries[181731] = { ["name"] = "Lacquered Larion Fang", ["text"] = "Binds when picked up\n\"Removing a fang from a slumbering Larion was one of many trials required for initiation into the House of Eyes.\"\nSell Price:" }
entries[181732] = { ["name"] = "Tribute of the Ambitious", ["text"] = "Binds when picked up\n\"Valuable items from the Undying Army's supply caches.\"\n<Right Click to Open>" }
entries[181733] = { ["name"] = "Tribute of the Duty-Bound", ["text"] = "Binds when picked up\n\"Valuable items from the Undying Army's supply caches.\"\n<Right Click to Open>" }
entries[181734] = { ["name"] = "Magi's Brand", ["text"] = "Binds when picked up\nUse: Add this Conduit to your collection at the Forge of Bonds.\n\nTouch of Magi accumulates an additional 6.0% of the damage you deal." }
entries[181735] = { ["name"] = "Hack and Slash", ["text"] = "Binds when picked up\nUse: Add this Conduit to your collection at the Forge of Bonds.\n\nRampage has a 24.0% chance to refund a charge of Raging Blow. (500ms cooldown)" }
entries[181736] = { ["name"] = "Flame Accretion", ["text"] = "Binds when picked up\nUse: Add this Conduit to your collection at the Forge of Bonds.\n\nFireball grants 2.5% Mastery when it fails to critically strike." }
entries[181737] = { ["name"] = "Nourishing Chi", ["text"] = "Binds when picked up\nUse: Add this Conduit to your collection at the Forge of Bonds.\n\nLife Cocoon increases healing over time received by an additional 18.8% , and this effect lingers for an additional 6 sec after the cocoon is removed." }
entries[181738] = { ["name"] = "Artifice of the Archmage", ["text"] = "Binds when picked up\nUse: Add this Conduit to your collection at the Forge of Bonds.\n\nYour Arcane Barrage has a 4.0% chance to grant 2 Arcane Charges." }
entries[181739] = { ["name"] = "Bag of Soul Ash", ["text"] = "Binds when picked up\n\"Contains 15000 Soul Ash and 5000 Soul Cinders.\"\n<Right Click to Open>\nSell Price:" }
entries[181740] = { ["name"] = "Evasive Stride", ["text"] = "Binds when picked up\nUse: Add this Conduit to your collection at the Forge of Bonds.\n\nDuring Shuffle, Heavy Stagger has a 2.5% chance to heal you instead of dealing damage." }
entries[181741] = { ["name"] = "Tribute of the Paragon", ["text"] = "Binds when picked up\n\"Valuable items from the forge-temples are contained within this tribute.\"\n<Right Click to Open>" }
entries[181742] = { ["name"] = "Walk with the Ox", ["text"] = "Binds when picked up\nUse: Add this Conduit to your collection at the Forge of Bonds.\n\nAbilities that grant Shuffle reduce the cooldown on Invoke Niuzao, the Black Ox by 0.5 sec, and Niuzao's Stomp deals an additional 25.0% damage." }
entries[181743] = { ["name"] = "Plume of the Archon", ["text"] = "Anima\nBinds when picked up\nUse: Infuse 250 stored Anima into your covenant's Reservoir.\nSell Price:" }
entries[181744] = { ["name"] = "Forgelite Ember", ["text"] = "Anima\nBinds when picked up\nUse: Infuse 5 stored Anima into your covenant's Reservoir.\nSell Price:" }
entries[181745] = { ["name"] = "Forgesmith's Coal", ["text"] = "Anima\nBinds when picked up\nUse: Infuse 35 stored Anima into your covenant's Reservoir.\nSell Price:" }
entries[181749] = { ["name"] = "Windswept Rising Glory", ["text"] = "Quest Item" }
entries[181756] = { ["name"] = "Incantation of Swiftness", ["text"] = "Binds when picked up\nUse: Add this Conduit to your collection at the Forge of Bonds.\n\nArcane\nInvisibility increases your movement speed by 18% for 6 sec.\n\nFire, Frost\nInvisibility increases your movement speed by 45% for 6 sec." }
entries[181757] = { ["name"] = "Lambent Vigil's Torch", ["text"] = "Quest Item" }
entries[181758] = { ["name"] = "Guisein Extractor", ["text"] = "Herbalism Tool\nEquip: +4 Herbalism Skill.\nRequires Classic Herbalism (1)\n\"Others see this as an instrument of torture, but the Maldraxxi use this to harvest herbs from the undulating terrain of their homeland.\"\nSell Price:" }
entries[181759] = { ["name"] = "Strike with Clarity", ["text"] = "Binds when picked up\nUse: Add this Conduit to your collection at the Forge of Bonds.\n\nWeapons of Order's duration is increased by 5.0 sec, and it increases your Mastery by an additional [([source value].92999983).1][([source value].3287499).1]% .", ["unresolvedValues"] = true }
entries[181760] = { ["name"] = "Calcified Pickaxe", ["text"] = "Mining Tool\nEquip: +4 Mining Skill.\nRequires Classic Mining (1)\nSell Price:" }
entries[181761] = { ["name"] = "The Grandmaster's Voucher", ["text"] = "Binds when picked up\nThis Item Begins a Quest\n\"This voucher begrudgingly verifies that the Grandmaster has lost a bet and intends to give the bearer the agreed sum. Au'narim at the Theater of Pain will approve and dispense said funds.\"" }
entries[181762] = { ["name"] = "Lush Widowbloom", ["text"] = "Quest Item" }
entries[181763] = { ["name"] = "Bonesmith's Hammer", ["text"] = "Blacksmithing Tool\nSell Price:" }
entries[181764] = { ["name"] = "Dermal Flayer", ["text"] = "Skinning Tool\nEquip: +4 Skinning Skill.\nRequires Skinning (1)\nSell Price:" }
entries[181765] = { ["name"] = "Marcel Mullby's Marker", ["text"] = "Binds when picked up\nThis Item Begins a Quest\n\"Never planning to bring a gift, Grandmaster Vole still had a good time and tossed this marker into the gift box. If you return it to Marcel he is sure to offer a sizable sum to get his marker back.\"" }
entries[181767] = { ["name"] = "Small Coin Purse", ["text"] = "Binds when picked up\n\"The initials GV are sown into the side, you should take it as an honor, Grandmaster Vole is not easily enteretained and rarely does he tip.\"\n<Right Click to Open>" }
entries[181769] = { ["name"] = "Tempest Barrier", ["text"] = "Binds when picked up\nUse: Add this Conduit to your collection at the Forge of Bonds.\n\nGain a shield that absorbs 4.0% of your maximum health for 15 sec after you Blink." }
entries[181770] = { ["name"] = "Bone Marrow Hops", ["text"] = "Binds when picked up\nUse: Add this Conduit to your collection at the Forge of Bonds.\n\nBonedust Brew's Shadow damage or healing is increased by 40.0% , and when Bonedust Brew deals Shadow damage or healing, its cooldown is reduced by 0.5 sec." }
entries[181771] = { ["name"] = "Stonehead's Best Bud Bracelet", ["text"] = "Binds when picked up\nDuration: 1 day (real time)" }
entries[181774] = { ["name"] = "Imbued Reflections", ["text"] = "Binds when picked up\nUse: Add this Conduit to your collection at the Forge of Bonds.\n\nFallen Order monks deal 36.3% more damage and healing." }
entries[181775] = { ["name"] = "Way of the Fae", ["text"] = "Binds when picked up\nUse: Add this Conduit to your collection at the Forge of Bonds.\n\nIncreases the initial damage of Faeline Stomp by 21.0% per target hit by that damage, up to a maximum of 105.0% additional damage." }
entries[181776] = { ["name"] = "Vicious Contempt", ["text"] = "Binds when picked up\nUse: Add this Conduit to your collection at the Forge of Bonds.\n\nBloodthirst deals 24.0% increased damage to enemies who are below 35% health." }
entries[181777] = { ["name"] = "Phaeton's Key", ["text"] = "Binds when picked up\nRequires level 60 to 60 ( 60)\n\"A key belonging to the runespeakers of the House of the Chosen.\"\nSell Price:" }
entries[181778] = { ["name"] = "Sack of Shinies", ["text"] = "Binds when picked up\n\"Rendle and Cudgelface's best collection of shinies hastily put into a large sack, because a good guest always leaves a gift.\"\n<Right Click to Open>\nSell Price:" }
entries[181779] = { ["name"] = "A \"Wrapped\" Weapon", ["text"] = "Binds when picked up\n\"It is very clearly a weapon, but which one...\"\n<Right Click to Open>\nSell Price:" }
